import{_ as o,o as a,c as t,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Troubleshooting: Audio Generation","description":"Fix issues with TTS voices, audio playback, and sync.","frontmatter":{"title":"Troubleshooting: Audio Generation","description":"Fix issues with TTS voices, audio playback, and sync."},"headers":[],"relativePath":"support/troubleshooting_audio.md","filePath":"support/troubleshooting_audio.md"}'),i={name:"support/troubleshooting_audio.md"};function n(s,e,u,l,d,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting-audio-generation" tabindex="-1">Troubleshooting: Audio Generation <a class="header-anchor" href="#troubleshooting-audio-generation" aria-label="Permalink to &quot;Troubleshooting: Audio Generation&quot;">​</a></h1><h2 id="_1-generate-audio-button-is-disabled" tabindex="-1">1. &quot;Generate Audio&quot; Button is Disabled <a class="header-anchor" href="#_1-generate-audio-button-is-disabled" aria-label="Permalink to &quot;1. &quot;Generate Audio&quot; Button is Disabled&quot;">​</a></h2><p><strong>Symptom:</strong> You are trying to generate audio for a scene, but the button is greyed out. <strong>Solution:</strong> Every spoken line must have a character assigned to it. Look for the dropdown menu next to the dialogue line in the Script Panel, and select a character from your Cast list.</p><h2 id="_2-audio-url-expired-audio-link-expired" tabindex="-1">2. Audio URL Expired (AUDIO_LINK_EXPIRED) <a class="header-anchor" href="#_2-audio-url-expired-audio-link-expired" aria-label="Permalink to &quot;2. Audio URL Expired (AUDIO_LINK_EXPIRED)&quot;">​</a></h2><p><strong>Symptom:</strong> Audio was playing fine yesterday, but today it fails to play or download. <strong>Cause:</strong> To protect your media from unauthorized scraping, Sanjeev AI uses Google Cloud Storage Signed URLs, which expire after 24 hours. <strong>Solution:</strong> Click the <strong>Refresh Links</strong> icon (circular arrows) in the Studio toolbar. The <code>refresher</code> backend agent will instantly mint new secure URLs for your entire project.</p><h2 id="_3-audio-cuts-off-early" tabindex="-1">3. Audio Cuts Off Early <a class="header-anchor" href="#_3-audio-cuts-off-early" aria-label="Permalink to &quot;3. Audio Cuts Off Early&quot;">​</a></h2><p><strong>Symptom:</strong> The generated voice stops speaking midway through a sentence. <strong>Cause:</strong></p><ul><li>The text block may exceed the TTS engine&#39;s character limit (approx 5000 characters per block).</li><li>Unusual special characters (like complex emojis or math symbols) can crash the TTS engine mid-sentence. <strong>Solution:</strong> Break long monologues into smaller, separate scenes. Remove any non-standard symbols from the script text.</li></ul><h2 id="_4-audio-playback-muted-on-safari" tabindex="-1">4. Audio Playback Muted on Safari <a class="header-anchor" href="#_4-audio-playback-muted-on-safari" aria-label="Permalink to &quot;4. Audio Playback Muted on Safari&quot;">​</a></h2><p><strong>Symptom:</strong> You press play on a scene preview, but hear no sound on an iPhone or Mac. <strong>Cause:</strong> Apple Safari strictly limits audio autoplay. <strong>Solution:</strong> You must interact with the webpage (click anywhere on the screen) at least once before Safari will permit audio playback.</p>',10)])])}const g=o(i,[["render",n]]);export{p as __pageData,g as default};
